// Extra languages live in renderer/locales/*.js and register themselves here.
Object.assign(STRINGS, window.NIGHTDOCK_LOCALES || {});

// Pick the best language for a list of system locales like ["nb-NO", "en-US"].
function matchLanguage(locales) {
  for (const raw of locales || []) {
    const l = String(raw || '').toLowerCase().replace('_', '-');
    const base = l.split('-')[0];
    if (base === 'nb' || base === 'nn' || base === 'no') return 'nb';
    if (base === 'zh') return /-(tw|hk|mo|hant)/.test(l) ? 'zh-TW' : 'zh';
    if (base === 'iw') return 'he';
    if (base === 'in') return 'id';
    if (STRINGS[base]) return base;
  }
  return 'en';
}

const HTML_LANG = { pt: 'pt-BR', zh: 'zh-CN', 'zh-TW': 'zh-TW' };
let current = 'en';
let plural = new Intl.PluralRules('en');
function setLanguage(code) {
  current = STRINGS[code] ? code : 'en';
  const tag = HTML_LANG[current] || current;
  document.documentElement.lang = tag;
  document.documentElement.dir = LANGUAGES.find((l) => l.code === current)?.rtl ? 'rtl' : 'ltr';
  try { plural = new Intl.PluralRules(tag); } catch { plural = new Intl.PluralRules('en'); }
}
function getLanguage() { return current; }

// Values: a string; [one, other]; or { zero, one, two, few, many, other } for languages with more forms.
function pick(v, n) {
  if (Array.isArray(v)) return Number(n) === 1 ? v[0] : v[1];
  if (v && typeof v === 'object') return v[plural.select(Number(n))] ?? v.other;
  return v;
}
function t(key, vars = {}) {
  let v = STRINGS[current] && STRINGS[current][key];
  if (v === undefined) v = STRINGS.en[key];
  if (v === undefined) return key;
  v = pick(v, vars.n);
  return String(v).replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
}

// Translate static markup: data-i18n (text), data-i18n-ph (placeholder), data-i18n-title (tooltip).
function translatePage(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll('[data-i18n-title]').forEach((el) => { el.title = t(el.dataset.i18nTitle); el.setAttribute('aria-label', el.title); });
}

window.i18n = { LANGUAGES, STRINGS, matchLanguage, setLanguage, getLanguage, t, translatePage };
